{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/parts/timeline.json
    A vertical list of events (an order's history): a dot on a line, the title, an optional text and the time. Newest first or oldest first is the caller's order.
    Props (p): items, className. *}
{var $k_TONE_DOT = ['gray' => 'bg-muted-foreground', 'green' => 'bg-emerald-500', 'blue' => 'bg-blue-500', 'amber' => 'bg-amber-500', 'red' => 'bg-red-500']}
{var $v_items = ($p['items'] ?? null)}
{capture $c_9}
  {capture $c_8}
    {foreach ui_l($v_items) as $v_item}
      {var $v_i = $iterator->counter0}
      {capture $c_7}
        {capture $c_1}
          {if ui_t(ui_lt($v_i, ui_sub(ui_len($v_items), 1)))}
            {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'absolute top-4 -bottom-0 w-px bg-border']])|noescape}
          {/if}
          {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => ui_s(ui_cnv(['mt-2 size-2 rounded-full', ui_at($k_TONE_DOT, ui_coalesce([ui_get($v_item, ['tone']), 'gray']))]))]])|noescape}
        {/capture}
        {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'relative flex w-2 shrink-0 justify-center'], 'children' => $c_1])|noescape}
        {capture $c_6}
          {capture $c_4}
            {capture $c_2}
              {=ui_text(ui_get($v_item, ['title']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Class' => 'm-0 text-sm font-bold text-foreground'], 'children' => $c_2])|noescape}
            {capture $c_3}
              {=ui_text(ui_get($v_item, ['time']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Class' => 'm-0 shrink-0 text-xs font-medium text-muted-foreground'], 'children' => $c_3])|noescape}
          {/capture}
          {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'flex flex-wrap items-baseline justify-between gap-x-4'], 'children' => $c_4])|noescape}
          {if ui_t(ui_get($v_item, ['text']))}
            {capture $c_5}
              {=ui_text(ui_get($v_item, ['text']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Class' => 'm-0 text-xs font-medium text-muted-foreground'], 'children' => $c_5])|noescape}
          {/if}
        {/capture}
        {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'flex min-w-0 flex-1 flex-col gap-0'], 'children' => $c_6])|noescape}
      {/capture}
      {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => 'relative flex min-w-0 gap-4 pb-4 last:pb-0', 'Attrs' => ui_attrs(['data-event', ui_get($v_item, ['id'])])], 'children' => $c_7])|noescape}
    {/foreach}
  {/capture}
  {=ui_include('ui/list/list.latte', ['p' => ['Class' => 'm-0 flex list-none flex-col p-0'], 'children' => $c_8])|noescape}
{/capture}
{=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s(ui_cnv(['min-w-0', ($p['className'] ?? '')])), 'Attrs' => ui_attrs(['data-slot', 'timeline'])], 'children' => $c_9])|noescape}
